mapper.select:
SELECT U.USER_NO, U.USER_RESIDENT_NO, U.USER_NAME, U.USER_EMAIL, U.USER_TEL, U.USER_PHONE, U.USER_POSITION_CD, C.CODE_NAME AS USER_POSITION_NAME, U.DEL_YN, U.CREATE_DT, U.UPDATE_DT, U.CREATE_ID, U.UPDATE_ID, U.INST_ID FROM T1000_USER U LEFT JOIN TOTAL_CODE C ON U.USER_POSITION_CD = C.CODE_ID AND C.GROUP_ID = 'A0' WHERE 1=1
AND U.INST_ID LIKE = #{instId}
AND U.USER_NAME LIKE '%' || #{userName} || '%'
AND U.USER_EMAIL LIKE '%' || #{userEmail} || '%'
AND U.DEL_YN = #{delYn}
AND U.USER_POSITION_CD = #{userPositionCd}
ORDER BY U.CREATE_DT DESC

mapper.insert:
INSERT INTO T1000_USER (
    USER_RESIDENT_NO, USER_NAME, USER_EMAIL, USER_TEL, USER_PHONE, USER_POSITION_CD,
    DEL_YN, CREATE_DT, CREATE_ID, INST_ID
) VALUES (
    #{userResidentNo}, #{userName}, #{userEmail}, #{userTel}, #{userPhone}, #{userPositionCd},
    'N', SYSDATE, #{createId}, #{instId}
)
